import { betterAuth, type BetterAuthAdvancedOptions, type BetterAuthOptions } from "better-auth"
import { drizzleAdapter } from "better-auth/adapters/drizzle"
import { admin, openAPI, emailOTP } from "better-auth/plugins"
import * as schemas from "../functions/schemas"
import { db } from "../functions"
import { env } from "../utils/cf-util.ts"

const isDevelopment = env.NODE_ENV === "development"

const advancedusage: BetterAuthAdvancedOptions = {
    defaultCookieAttributes: {
        secure: !isDevelopment,
        partitioned: !isDevelopment,
        httpOnly: true,
        sameSite: isDevelopment ? 'lax' : 'none'
    },
    crossSubDomainCookies: {
        enabled: !isDevelopment
    },
    ipAddress: {
        ipAddressHeaders: ["x-client-ip", "x-forwarded-for", "cf-connecting-ip"],
        disableIpTracking: false
    }
}

const socialProviders: BetterAuthOptions['socialProviders'] = {
    github: {
        clientId: env.GITHUB_CLIENT_ID,
        clientSecret: env.GITHUB_CLIENT_SECRET,
        redirectURI: isDevelopment
            ? 'http://localhost:3000/api/auth/callback/github'
            : undefined
    }
}

export const auth = betterAuth({
    trustedOrigins: isDevelopment ? [
        'http://localhost:300*',
        'http://localhost:3000',
        'http://localhost:3001',
    ] : [
        'https://**.pherus.org',
        'https://pherus.org',
    ],
    baseURL: env.BETTER_AUTH_URL,
    secret: env.BETTER_AUTH_SECRET,
    experimental: { joins: true },
    database: drizzleAdapter(db.getDatabase(), {
        schema: schemas,
        provider: 'sqlite',
        camelCase: true
    }),
    emailAndPassword: { enabled: false },
    socialProviders,
    advanced: advancedusage,
    logger: {
        enabled: isDevelopment,
        level: "debug",
        log(level, message, ...args) {
            console.log("auth:debug:=:", level, message, ...args)
        },
    },
    plugins: [
        admin(),
        openAPI({ path: '/docs' }),
        emailOTP({
            async sendVerificationOTP({ email, otp, type }) {
                console.log(email, otp, type)
            }
        })
    ]
})
